return ['up' => [
// Named onboarding / exit templates (one default per kind) and their task list
"CREATE TABLE hr_templates (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind ENUM('onboarding','exit') NOT NULL, name VARCHAR(150) NOT NULL, description VARCHAR(500) NULL, is_default TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, KEY idx_hrt_kind (kind))$t",
"CREATE TABLE hr_template_tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_id INT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, description VARCHAR(1000) NULL, task_type $types NOT NULL DEFAULT 'task', owner $owners NOT NULL DEFAULT 'hr', due_days SMALLINT NOT NULL DEFAULT 0, company_doc_id INT UNSIGNED NULL, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, KEY idx_htt_tpl (template_id, position), CONSTRAINT fk_htt_tpl FOREIGN KEY (template_id) REFERENCES hr_templates(id) ON DELETE CASCADE)$t",
// One onboarding or exit run per employee (data kept when cancelled)
"CREATE TABLE hr_processes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, kind ENUM('onboarding','exit') NOT NULL, template_id INT UNSIGNED NULL, template_name VARCHAR(150) NULL, status ENUM('active','paused','completed','cancelled') NOT NULL DEFAULT 'active', start_date DATE NOT NULL, exit_type ENUM('resignation','termination','contract_end','other') NULL, last_working_day DATE NULL, deactivate_on_lwd TINYINT(1) NOT NULL DEFAULT 0, deactivated_at DATETIME NULL, note VARCHAR(1000) NULL, started_by INT UNSIGNED NULL, started_at DATETIME NOT NULL, paused_at DATETIME NULL, completed_at DATETIME NULL, completed_by INT UNSIGNED NULL, cancelled_at DATETIME NULL, cancelled_by INT UNSIGNED NULL, cancel_reason VARCHAR(500) NULL, KEY idx_hrp_user (user_id, kind, status), KEY idx_hrp_status (status, kind), CONSTRAINT fk_hrp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE)$t",
"CREATE TABLE hr_process_tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, description VARCHAR(1000) NULL, task_type $types NOT NULL DEFAULT 'task', owner $owners NOT NULL DEFAULT 'hr', due_date DATE NULL, company_doc_id INT UNSIGNED NULL, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, status ENUM('pending','submitted','rejected','done','skipped') NOT NULL DEFAULT 'pending', done_at DATETIME NULL, done_by INT UNSIGNED NULL, reminded_on DATE NULL, KEY idx_hpt_proc (process_id, position), KEY idx_hpt_user (user_id, status), KEY idx_hpt_due (status, due_date), CONSTRAINT fk_hpt_proc FOREIGN KEY (process_id) REFERENCES hr_processes(id) ON DELETE CASCADE)$t",
// Files people add for a task or a company document that needs a signature (file in core `files`, entity_type 'hr_upload'); purpose 'provided' = HR gives the employee a file to download
"CREATE TABLE hr_uploads (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, task_id INT UNSIGNED NULL, company_doc_id INT UNSIGNED NULL, purpose ENUM('submission','provided') NOT NULL DEFAULT 'submission', file_id INT UNSIGNED NULL, original_name VARCHAR(190) NULL, uploaded_by INT UNSIGNED NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', review_note VARCHAR(500) NULL, reviewed_by INT UNSIGNED NULL, reviewed_at DATETIME NULL, created_at DATETIME NOT NULL, KEY idx_hru_task (task_id), KEY idx_hru_doc (company_doc_id, user_id), KEY idx_hru_status (status), CONSTRAINT fk_hru_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE)$t",
// Employee asks HR to delete an upload after the self-delete window (kept after the upload is gone)
"CREATE TABLE hr_delete_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, upload_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, task_id INT UNSIGNED NULL, file_name VARCHAR(190) NULL, requested_by INT UNSIGNED NOT NULL, reason VARCHAR(500) NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', decided_by INT UNSIGNED NULL, decided_at DATETIME NULL, decision_note VARCHAR(500) NULL, created_at DATETIME NOT NULL, KEY idx_hdr_upload (upload_id, status), KEY idx_hdr_status (status), CONSTRAINT fk_hdr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE)$t",
"ALTER TABLE company_documents ADD COLUMN requires_signature TINYINT(1) NOT NULL DEFAULT 0 AFTER requires_ack",
